SELECT page, duration_sec_bucket, latest_event_time, unique_pages FROM (SELECT page, CASE WHEN duration_sec >= 422 THEN 'high' WHEN duration_sec >= 101 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, MAX(event_time) AS latest_event_time, COUNT(DISTINCT duration_sec) AS unique_pages FROM web_events GROUP BY page, CASE WHEN duration_sec >= 422 THEN 'high' WHEN duration_sec >= 101 THEN 'mid' ELSE 'low' END) AS x WHERE unique_pages > 9;
